insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M52601','listening',1,1,'choice','','[{"key": "A", "text": "支付对象错误"}, {"key": "B", "text": "没和商家沟通"}, {"key": "C", "text": "二维码有问题"}, {"key": "D", "text": "不会用高科技"}]'::jsonb,'C','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эмэгтэй «商家的二维码出问题了» гэж шууд хэлсэн тул шалтгаан нь QR код гэмтэлтэй байсан.',46.36,87.41,'女：昨天去商场买衣服，扫码支付一直失败。
男：怎么回事啊？
女：商家的二维码出问题了，和他沟通了半天才解决，费了不少精力。
男：高科技也有让人头疼的时候。
问：女的扫码支付为什么一直失败？','{"transcript": [{"zh": "女：昨天去商场买衣服，扫码支付一直失败。", "pinyin": "nǚ: zuó tiān qù shāng chǎng mǎi yī fú， sǎo mǎ zhī fù yì zhí shī bài。", "mn": "Эм: Өчигдөр худалдааны төвд хувцас авахдаа QR кодоор төлөхөд байнга амжилтгүй болсон."}, {"zh": "男：怎么回事啊？", "pinyin": "nán: zěn me huí shì a？", "mn": "Эр: Яасан юм бэ?"}, {"zh": "女：商家的二维码出问题了，和他沟通了半天才解决，费了不少精力。", "pinyin": "nǚ: shāng jiā de èr wéi mǎ chū wèn tí le， hé tā gōu tōng le bàn tiān cái jiě jué， fèi le bù shǎo jīng lì。", "mn": "Эм: Худалдагчийн QR код гэмтэлтэй байсан. Түүнтэй удаан ярилцаж байж шийдсэн, нилээд хүч зарлаа."}, {"zh": "男：高科技也有让人头疼的时候。", "pinyin": "nán: gāo kē jì yě yǒu ràng rén tóu téng de shí hòu。", "mn": "Эр: Өндөр технологи ч заримдаа толгойгоо өвтгөдөг юм даа."}, {"zh": "问：女的扫码支付为什么一直失败？", "pinyin": "wèn: nǚ de sǎo mǎ zhī fù wèi shén me yì zhí shī bài？", "mn": "Асуулт: Эмэгтэй яагаад QR кодоор төлж чадаагүй вэ?"}], "key": "商家的二维码出问题了", "keyMn": "Худалдагчийн QR код гэмтэлтэй байсан", "why": "Эмэгтэй «商家的二维码出问题了» гэж шууд хэлсэн тул шалтгаан нь QR код гэмтэлтэй байсан.", "wrong": {"A": "Тэр худалдагчийн QR кодыг уншуулсан, төлөх хүн буруу биш.", "B": "Худалдагчтай удаан ярьж байж шийдсэн, энэ нь шалтгаан биш үр дүн.", "D": "Эр «高科技也有让人头疼的时候» гэсэн, эмэгтэй технологи хэрэглэж чадахгүй гэсэн үг биш."}, "words": [{"zh": "扫码", "pinyin": "sǎomǎ", "mn": "QR код уншуулах"}, {"zh": "支付", "pinyin": "zhīfù", "mn": "төлбөр хийх"}, {"zh": "二维码", "pinyin": "èrwéimǎ", "mn": "QR код"}, {"zh": "沟通", "pinyin": "gōutōng", "mn": "харилцах, ярилцах"}]}'::jsonb),
('M52601','listening',1,2,'choice','','[{"key": "A", "text": "查高铁时间"}, {"key": "B", "text": "选飞机座位"}, {"key": "C", "text": "在酒店点餐"}, {"key": "D", "text": "订餐厅座位"}]'::jsonb,'D','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «预订今晚酒店西餐厅的座位» гэж зорилгоо шууд хэлсэн, тэгэхээр ресторанд суудал захиалж байна.',87.71,127.12,'男：你好！我想预订今晚酒店西餐厅的座位，两位用餐，六点半到。
女：没问题。请问您贵姓？
男：免贵姓孙。最好是靠窗的座位，安静一点儿的位置。
女：好的，孙先生，靠窗座位已为您预留。
问：男的正在做什么？','{"transcript": [{"zh": "男：你好！我想预订今晚酒店西餐厅的座位，两位用餐，六点半到。", "pinyin": "nán: nǐ hǎo！ wǒ xiǎng yù dìng jīn wǎn jiǔ diàn xī cān tīng de zuò wèi， liǎng wèi yòng cān， liù diǎn bàn dào。", "mn": "Эр: Сайн байна уу! Өнөө орой зочид буудлын европ хоолны газарт суудал захиалъя. Хоёр хүн, зургаа хагаст очно."}, {"zh": "女：没问题。请问您贵姓？", "pinyin": "nǚ: méi wèn tí。 qǐng wèn nín guì xìng？", "mn": "Эм: Болно оо. Таны овог хэн бэ?"}, {"zh": "男：免贵姓孙。最好是靠窗的座位，安静一点儿的位置。", "pinyin": "nán: miǎn guì xìng sūn。 zuì hǎo shì kào chuāng de zuò wèi， ān jìng yì diǎn ér de wèi zhì。", "mn": "Эр: Миний овог Сүн. Аль болох цонхны дэргэд, нам гүм газар байвал сайн."}, {"zh": "女：好的，孙先生，靠窗座位已为您预留。", "pinyin": "nǚ: hǎo de， sūn xiān shēng， kào chuāng zuò wèi yǐ wèi nín yù liú。", "mn": "Эм: За, ноён Сүн, цонхны дэргэдэх суудлыг танд үлдээлээ."}, {"zh": "问：男的正在做什么？", "pinyin": "wèn: nán de zhèng zài zuò shén me？", "mn": "Асуулт: Эр юу хийж байна вэ?"}], "key": "我想预订……西餐厅的座位", "keyMn": "Би европ хоолны газрын суудал захиалмаар байна", "why": "Эр «预订今晚酒店西餐厅的座位» гэж зорилгоо шууд хэлсэн, тэгэхээр ресторанд суудал захиалж байна.", "wrong": {"A": "«六点半到» нь хоолны цаг, өндөр хурдны галт тэрэгтэй хамаагүй.", "B": "«靠窗的座位» нь рестораны суудал, онгоцны суудал биш.", "C": "Эр хоол захиалаагүй, суудал захиалсан."}, "words": [{"zh": "预订", "pinyin": "yùdìng", "mn": "урьдчилан захиалах"}, {"zh": "西餐厅", "pinyin": "xīcāntīng", "mn": "европ хоолны газар"}, {"zh": "靠窗", "pinyin": "kào chuāng", "mn": "цонхны дэргэд"}, {"zh": "预留", "pinyin": "yùliú", "mn": "урьдаас үлдээх"}]}'::jsonb),
('M52601','listening',1,3,'choice','','[{"key": "A", "text": "政府公务员"}, {"key": "B", "text": "汽车工程师"}, {"key": "C", "text": "建筑设计师"}, {"key": "D", "text": "数据分析师"}]'::jsonb,'B','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «想去车企做一名工程师» гэж хэлсэн тул автомашины инженер болохыг хүсдэг.',127.42,179.47,'女：现在就业压力比较大，你打算考公务员还是去企业工作？
男：公务员很稳定，待遇也不错。但是我不想放弃自己的专业，还是想去车企做一名工程师，这样也能发挥我的优势。
女：挺好的，你可以多参加一些各大车企的校园招聘。
男：是的，我也投出了几份简历，但现在还没有接到面试通知。
问：男的想做什么工作？','{"transcript": [{"zh": "女：现在就业压力比较大，你打算考公务员还是去企业工作？", "pinyin": "nǚ: xiàn zài jiù yè yā lì bǐ jiào dà， nǐ dǎ suàn kǎo gōng wù yuán hái shì qù qǐ yè gōng zuò？", "mn": "Эм: Одоо ажил олоход хэцүү байна. Чи төрийн албанд орох уу, компанид ажиллах уу?"}, {"zh": "男：公务员很稳定，待遇也不错。但是我不想放弃自己的专业，还是想去车企做一名工程师，这样也能发挥我的优势。", "pinyin": "nán: gōng wù yuán hěn wěn dìng， dài yù yě bù cuò。 dàn shì wǒ bù xiǎng fàng qì zì jǐ de zhuān yè， hái shì xiǎng qù chē qǐ zuò yī míng gōng chéng shī， zhè yàng yě néng fā huī wǒ de yōu shì。", "mn": "Эр: Төрийн алба тогтвортой, цалин хөлс ч сайн. Гэхдээ би мэргэжлээ орхиж барахгүй, автомашины компанид инженер болмоор байна. Тэгвэл давуу талаа гаргаж чадна."}, {"zh": "女：挺好的，你可以多参加一些各大车企的校园招聘。", "pinyin": "nǚ: tǐng hǎo de， nǐ kě yǐ duō cān jiā yī xiē gè dà chē qǐ de xiào yuán zhāo pìn。", "mn": "Эм: Сайн байна. Машины томоохон компаниудын оюутан сонгон шалгаруулалтад олуулаа оролцоорой."}, {"zh": "男：是的，我也投出了几份简历，但现在还没有接到面试通知。", "pinyin": "nán: shì de， wǒ yě tóu chū le jǐ fèn jiǎn lì， dàn xiàn zài hái méi yǒu jiē dào miàn shì tōng zhī。", "mn": "Эр: Тийм ээ. Би хэдэн анкет явуулсан ч одоохондоо ярилцлагын урилга ирээгүй байна."}, {"zh": "问：男的想做什么工作？", "pinyin": "wèn: nán de xiǎng zuò shén me gōng zuò？", "mn": "Асуулт: Эр ямар ажил хийхийг хүсэж байна вэ?"}], "key": "想去车企做一名工程师", "keyMn": "Автомашины компанид инженер болмоор байна", "why": "Эр «想去车企做一名工程师» гэж хэлсэн тул автомашины инженер болохыг хүсдэг.", "wrong": {"A": "Төрийн алба тогтвортой гэж хэлсэн ч мэргэжлээ орхихыг хүсэхгүй байгаагаа хэлсэн.", "C": "Барилгын зураач ярианд гараагүй.", "D": "Өгөгдлийн шинжээч ярианд гараагүй."}, "words": [{"zh": "公务员", "pinyin": "gōngwùyuán", "mn": "төрийн албан хаагч"}, {"zh": "车企", "pinyin": "chēqǐ", "mn": "автомашины компани"}, {"zh": "工程师", "pinyin": "gōngchéngshī", "mn": "инженер"}, {"zh": "简历", "pinyin": "jiǎnlì", "mn": "анкет, CV"}]}'::jsonb),
('M52601','listening',1,4,'choice','','[{"key": "A", "text": "在家吃火锅"}, {"key": "B", "text": "要收拾家务"}, {"key": "C", "text": "去单位加班"}, {"key": "D", "text": "去超市买菜"}]'::jsonb,'C','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эмэгтэй «明天我要加班» гэж шууд хэлсэн, тиймээс маргааш ажил дээрээ илүү цагаар ажиллана.',179.77,227.06,'男：周末咱们在家吃火锅吧，热热乎乎的，超满足！
女：算了吧。家里空间小，吃完火锅会一直有味道，而且收拾家务也特别麻烦。
男：我来刷盘子、刷碗怎么样？咱俩紧密配合，家务很快就可以搞定。
女：那好吧。明天我要加班，你晚上去超市买菜吧。
问：女的明天有什么计划？','{"transcript": [{"zh": "男：周末咱们在家吃火锅吧，热热乎乎的，超满足！", "pinyin": "nán: zhōu mò zán men zài jiā chī huǒ guō ba， rè rè hū hū de， chāo mǎn zú！", "mn": "Эр: Амралтын өдөр гэртээ галтай тогоо идье, халуун сайхан, үнэхээр хангалуун шүү!"}, {"zh": "女：算了吧。家里空间小，吃完火锅会一直有味道，而且收拾家务也特别麻烦。", "pinyin": "nǚ: suàn le ba。 jiā lǐ kōng jiān xiǎo， chī wán huǒ guō huì yì zhí yǒu wèi dào， ér qiě shōu shí jiā wù yě tè bié má fán。", "mn": "Эм: Больё доо. Манайх явцуу, галтай тогоо идсэн хойно үнэр удаан үлддэг, дээр нь цэвэрлэх нь бас маш төвөгтэй."}, {"zh": "男：我来刷盘子、刷碗怎么样？咱俩紧密配合，家务很快就可以搞定。", "pinyin": "nán: wǒ lái shuā pán zi、 shuā wǎn zěn me yàng？ zán liǎ jǐn mì pèi hé， jiā wù hěn kuài jiù kě yǐ gǎo dìng。", "mn": "Эр: Би аяга таваг угаая, яасан бэ? Хоёулаа хамтраад хийвэл гэрийн ажил хурдан дуусна."}, {"zh": "女：那好吧。明天我要加班，你晚上去超市买菜吧。", "pinyin": "nǚ: nà hǎo ba。 míng tiān wǒ yào jiā bān， nǐ wǎn shàng qù chāo shì mǎi cài ba。", "mn": "Эм: За тэгвэл дээ. Маргааш би ажил дээрээ илүү цагаар ажиллана, чи орой дэлгүүрээс хүнсээ авчих."}, {"zh": "问：女的明天有什么计划？", "pinyin": "wèn: nǚ de míng tiān yǒu shén me jì huà？", "mn": "Асуулт: Эмэгтэй маргааш ямар төлөвлөгөөтэй вэ?"}], "key": "明天我要加班", "keyMn": "Маргааш би илүү цагаар ажиллана", "why": "Эмэгтэй «明天我要加班» гэж шууд хэлсэн, тиймээс маргааш ажил дээрээ илүү цагаар ажиллана.", "wrong": {"A": "Галтай тогоо нь амралтын өдрийн санал, эмэгтэйн маргаашийн төлөвлөгөө биш.", "B": "Эмэгтэй гэрийн ажил төвөгтэй гэж хэлсэн, гэхдээ маргаашийн төлөвлөгөө биш.", "D": "Дэлгүүрт хүнс авахыг эр хийнэ."}, "words": [{"zh": "火锅", "pinyin": "huǒguō", "mn": "галтай тогоо"}, {"zh": "收拾", "pinyin": "shōushi", "mn": "цэвэрлэх, эмхлэх"}, {"zh": "加班", "pinyin": "jiābān", "mn": "илүү цагаар ажиллах"}, {"zh": "单位", "pinyin": "dānwèi", "mn": "ажлын газар"}], "trap": "«Маргааш» гэдэг нь асуултын түлхүүр: амралтын өдрийн санаа биш, маргаашийн төлөвлөгөөг сонсоорой."}'::jsonb),
('M52601','listening',1,5,'choice','','[{"key": "A", "text": "获得了冠军"}, {"key": "B", "text": "有强大实力"}, {"key": "C", "text": "体力有优势"}, {"key": "D", "text": "发挥得很好"}]'::jsonb,'B','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр Бээжин баг аварга болно гэж үзсэн шалтгаан нь «靠实力说话», өөрөөр хэлбэл тэд хүчтэй баг.',227.36,275.42,'女：明天的决赛你预测哪个队能赢？
男：我虽然支持广东队，但我觉得北京队能获得冠军，毕竟在赛场上是靠实力说话的。
女：广东队的球员虽然大赛经验不足，但是年轻，体力上有优势。再说，比赛时运气也很重要。
男：希望明天他们都能好好发挥吧。
问：关于北京队，可以知道什么？','{"transcript": [{"zh": "女：明天的决赛你预测哪个队能赢？", "pinyin": "nǚ: míng tiān de jué sài nǐ yù cè nǎ ge duì néng yíng？", "mn": "Эм: Маргаашийн финалд аль баг хожих бол гэж чи бодож байна?"}, {"zh": "男：我虽然支持广东队，但我觉得北京队能获得冠军，毕竟在赛场上是靠实力说话的。", "pinyin": "nán: wǒ suī rán zhī chí guǎng dōng duì， dàn wǒ jué de běi jīng duì néng huò dé guàn jūn， bì jìng zài sài chǎng shàng shì kào shí lì shuō huà de。", "mn": "Эр: Би Гуандун багийг дэмждэг ч Бээжин баг аварга болно гэж бодож байна. Тэмцээнд эцсийн дүндээ хүч чадал л шийддэг шүү дээ."}, {"zh": "女：广东队的球员虽然大赛经验不足，但是年轻，体力上有优势。再说，比赛时运气也很重要。", "pinyin": "nǚ: guǎng dōng duì de qiú yuán suī rán dà sài jīng yàn bù zú， dàn shì nián qīng， tǐ lì shàng yǒu yōu shì。 zài shuō， bǐ sài shí yùn qì yě hěn zhòng yào。", "mn": "Эм: Гуандунгийн тоглогчид том тэмцээний туршлага дутуу ч залуу учраас биеийн хүч талаасаа давуу. Дээр нь тэмцээнд аз ч чухал."}, {"zh": "男：希望明天他们都能好好发挥吧。", "pinyin": "nán: xī wàng míng tiān tā men dōu néng hǎo hǎo fā huī ba。", "mn": "Эр: Хоёулаа маргааш сайн тоглоосой гэж хүсье."}, {"zh": "问：关于北京队，可以知道什么？", "pinyin": "wèn: guān yú běi jīng duì， kě yǐ zhī dào shén me？", "mn": "Асуулт: Бээжин багийн тухай юуг мэдэж болох вэ?"}], "key": "北京队能获得冠军，毕竟在赛场上是靠实力说话的", "keyMn": "Бээжин баг аварга болно, тэмцээнд хүч чадал л шийддэг", "why": "Эр Бээжин баг аварга болно гэж үзсэн шалтгаан нь «靠实力说话», өөрөөр хэлбэл тэд хүчтэй баг.", "wrong": {"A": "Финал маргааш болно, одоохондоо аварга болоогүй.", "C": "«体力上有优势» гэдгийг эмэгтэй Гуандун багийн тухай хэлсэн.", "D": "Эр хоёр багийг маргааш сайн тоглоосой гэж хүссэн, одоо сайн тоглосон гэсэн үг биш."}, "words": [{"zh": "决赛", "pinyin": "juésài", "mn": "финал"}, {"zh": "冠军", "pinyin": "guànjūn", "mn": "аварга"}, {"zh": "实力", "pinyin": "shílì", "mn": "бодит чадал, хүч"}, {"zh": "发挥", "pinyin": "fāhuī", "mn": "чадлаа гаргах"}]}'::jsonb),
('M52601','listening',1,6,'choice','','[{"key": "A", "text": "一月"}, {"key": "B", "text": "四月"}, {"key": "C", "text": "七月"}, {"key": "D", "text": "十月"}]'::jsonb,'A','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'«冷空气», «强降雪», «路面会结冰» гэсэн мэдээ нь өвлийн агуулгатай, Бээжинд ийм цаг агаар 1 дүгээр сард болно.',275.72,317.26,'男：天气预报说北京周末要来一轮新的冷空气。
女：那可太糟糕了！我和朋友还约着去爬山呢。
男：据说这轮冷空气会带来强降雪，估计到时路面会结冰。
女：好吧，看来只能取消计划待在家里了。
问：对话最可能发生在哪个月份？','{"transcript": [{"zh": "男：天气预报说北京周末要来一轮新的冷空气。", "pinyin": "nán: tiān qì yù bào shuō běi jīng zhōu mò yào lái yī lún xīn de lěng kōng qì。", "mn": "Эр: Цаг агаарын мэдээгээр Бээжинд амралтын өдрүүдэд дахин нэг удаа хүйтэн агаар орно гэнэ."}, {"zh": "女：那可太糟糕了！我和朋友还约着去爬山呢。", "pinyin": "nǚ: nà kě tài zāo gāo le！ wǒ hé péng yǒu hái yuē zhe qù pá shān ne。", "mn": "Эм: Ёстой муу юу! Би найзтайгаа ууланд авирахаар болсон байсан юм."}, {"zh": "男：据说这轮冷空气会带来强降雪，估计到时路面会结冰。", "pinyin": "nán: jù shuō zhè lún lěng kōng qì huì dài lái qiáng jiàng xuě， gū jì dào shí lù miàn huì jié bīng。", "mn": "Эр: Энэ удаагийн хүйтэн агаар их цас оруулна гэнэ, тэр үед зам мөстөнө байх."}, {"zh": "女：好吧，看来只能取消计划待在家里了。", "pinyin": "nǚ: hǎo ba， kàn lái zhǐ néng qǔ xiāo jì huà dài zài jiā lǐ le。", "mn": "Эм: За яахав, төлөвлөгөөгөө цуцлаад гэртээ суухаас өөр аргагүй юм байна."}, {"zh": "问：对话最可能发生在哪个月份？", "pinyin": "wèn: duì huà zuì kě néng fā shēng zài nǎ ge yuè fèn？", "mn": "Асуулт: Яриа аль сард болсон байх вэ?"}], "key": "冷空气、强降雪、路面会结冰", "keyMn": "Хүйтэн агаар, их цас, зам мөстөнө", "why": "«冷空气», «强降雪», «路面会结冰» гэсэн мэдээ нь өвлийн агуулгатай, Бээжинд ийм цаг агаар 1 дүгээр сард болно.", "wrong": {"B": "4 дүгээр сар хавар, их цас орох боломж бага.", "C": "7 дугаар сар зун.", "D": "10 дугаар сар намар, зам мөстөх нь ховор."}, "words": [{"zh": "冷空气", "pinyin": "lěngkōngqì", "mn": "хүйтэн агаар"}, {"zh": "强降雪", "pinyin": "qiáng jiàngxuě", "mn": "их хэмжээний цас"}, {"zh": "结冰", "pinyin": "jiébīng", "mn": "мөстөх"}, {"zh": "取消", "pinyin": "qǔxiāo", "mn": "цуцлах"}]}'::jsonb),
('M52601','listening',1,7,'choice','','[{"key": "A", "text": "下载手机应用"}, {"key": "B", "text": "连上网络充值"}, {"key": "C", "text": "开车去营业厅"}, {"key": "D", "text": "给客服打电话"}]'::jsonb,'B','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «连上Wi-Fi把钱充上» гэсэн, өөрөөр хэлбэл сүлжээнд холбогдоод утасныхаа багцыг цэнэглэнэ.',317.56,356.03,'女：你手机是不是停机了？
男：哎呀，应该是套餐到期了，我忘了充值。
女：我说怎么给你打电话打不通呢。那你赶紧登录APP充上吧。
男：这会儿手机网络也断了，我一会儿连上Wi-Fi把钱充上。
问：男的要做什么？','{"transcript": [{"zh": "女：你手机是不是停机了？", "pinyin": "nǚ: nǐ shǒu jī shì bú shì tíng jī le？", "mn": "Эм: Чиний утас зогссон юм биш үү?"}, {"zh": "男：哎呀，应该是套餐到期了，我忘了充值。", "pinyin": "nán: āi yā， yīng gāi shì tào cān dào qī le， wǒ wàng le chōng zhí。", "mn": "Эр: Аа, багц дууссан байх нь ээ, цэнэглэхээ мартчихаж."}, {"zh": "女：我说怎么给你打电话打不通呢。那你赶紧登录APP充上吧。", "pinyin": "nǚ: wǒ shuō zěn me gěi nǐ dǎ diàn huà dǎ bù tōng ne。 nà nǐ gǎn jǐn dēng lù APP chōng shàng ba。", "mn": "Эм: Тийм болохоор л чамруу залгахад холбогдохгүй байсан юм байна. Яаралтай аппаараа орж цэнэглэчих."}, {"zh": "男：这会儿手机网络也断了，我一会儿连上Wi-Fi把钱充上。", "pinyin": "nán: zhè huì er shǒu jī wǎng luò yě duàn le， wǒ yī huì er lián shàng Wi-Fi bǎ qián chōng shàng。", "mn": "Эр: Одоо утасны сүлжээ ч тасарчихсан байна, жаахан хойно Wi-Fi-д холбогдоод мөнгөө хийчихье."}, {"zh": "问：男的要做什么？", "pinyin": "wèn: nán de yào zuò shén me？", "mn": "Асуулт: Эр юу хийх вэ?"}], "key": "我一会儿连上Wi-Fi把钱充上", "keyMn": "Би жаахан хойно Wi-Fi-д холбогдоод мөнгө цэнэглэнэ", "why": "Эр «连上Wi-Fi把钱充上» гэсэн, өөрөөр хэлбэл сүлжээнд холбогдоод утасныхаа багцыг цэнэглэнэ.", "wrong": {"A": "Эмэгтэй «登录APP» гэсэн, апп татаж авах тухай яриагүй.", "C": "Автомашинаар үйлчилгээний төв рүү явах тухай ярианд байхгүй.", "D": "Үйлчилгээний төвд залгах тухай ярианд байхгүй."}, "words": [{"zh": "停机", "pinyin": "tíngjī", "mn": "утас хаагдах"}, {"zh": "套餐", "pinyin": "tàocān", "mn": "багц (тариф)"}, {"zh": "充值", "pinyin": "chōngzhí", "mn": "данс цэнэглэх"}, {"zh": "登录", "pinyin": "dēnglù", "mn": "нэвтрэх"}]}'::jsonb),
('M52601','listening',1,8,'choice','','[{"key": "A", "text": "实验设计有失误"}, {"key": "B", "text": "产量预计不合理"}, {"key": "C", "text": "生产部门效率低"}, {"key": "D", "text": "设备软件有问题"}]'::jsonb,'D','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эмэгтэй «新设备软件存在问题» гэж шалтгааныг хэлсэн, тиймээс асуудал төхөөрөмжийн программ дээр байна.',356.33,402.87,'男：这次实验中，新型电池的产量怎么样？
女：不太理想。更换设备后，产量不但没有提高，反而比预计少了近两成呢。
男：这太奇怪了，是哪里出了问题？
女：根据目前的情况来看，很可能是由于新设备软件存在问题，导致其无法长时间正常运行或与其他部件协调工作。
问：女的是什么意思？','{"transcript": [{"zh": "男：这次实验中，新型电池的产量怎么样？", "pinyin": "nán: zhè cì shí yàn zhōng， xīn xíng diàn chí de chǎn liàng zěn me yàng？", "mn": "Эр: Энэ удаагийн туршилтад шинэ төрлийн батерейны гарц ямар байна?"}, {"zh": "女：不太理想。更换设备后，产量不但没有提高，反而比预计少了近两成呢。", "pinyin": "nǚ: bù tài lǐ xiǎng。 gēng huàn shè bèi hòu， chǎn liàng bù dàn méi yǒu tí gāo， fǎn ér bǐ yù jì shǎo le jìn liǎng chéng ne。", "mn": "Эм: Сайнгүй. Төхөөрөмж сольсны дараа гарц нэмэгдэхгүй байснаас гадна, төлөвлөснөөс бараг хоёр аравны нэгээр буурсан."}, {"zh": "男：这太奇怪了，是哪里出了问题？", "pinyin": "nán: zhè tài qí guài le， shì nǎ lǐ chū le wèn tí？", "mn": "Эр: Үнэхээр сонин юм, яасан юм бол?"}, {"zh": "女：根据目前的情况来看，很可能是由于新设备软件存在问题，导致其无法长时间正常运行或与其他部件协调工作。", "pinyin": "nǚ: gēn jù mù qián de qíng kuàng lái kàn， hěn kě néng shì yóu yú xīn shè bèi ruǎn jiàn cún zài wèn tí， dǎo zhì qí wú fǎ zhǎng shí jiān zhèng cháng yùn xíng huò yǔ qí tā bù jiàn xié tiáo gōng zuò。", "mn": "Эм: Одоогийн нөхцөлөөс харахад шинэ төхөөрөмжийн программ хангамжид асуудалтай, ингээд удаан хугацаанд хэвийн ажиллаж чадахгүй эсвэл бусад хэсэгтэйгээ зохицож ажиллаж чадахгүй байгаа бололтой."}, {"zh": "问：女的是什么意思？", "pinyin": "wèn: nǚ de shì shén me yì si？", "mn": "Асуулт: Эмэгтэй юу гэсэн үг вэ?"}], "key": "新设备软件存在问题", "keyMn": "Шинэ төхөөрөмжийн программ хангамжид асуудал бий", "why": "Эмэгтэй «新设备软件存在问题» гэж шалтгааныг хэлсэн, тиймээс асуудал төхөөрөмжийн программ дээр байна.", "wrong": {"A": "Туршилтын загварын алдааны талаар яриагүй.", "B": "«比预计少» гэж хэлсэн ч төлөвлөгөө буруу гэж хэлээгүй.", "C": "Үйлдвэрлэлийн хэлтсийн үр ашгийн тухай яриагүй."}, "words": [{"zh": "实验", "pinyin": "shíyàn", "mn": "туршилт"}, {"zh": "电池", "pinyin": "diànchí", "mn": "батарей"}, {"zh": "产量", "pinyin": "chǎnliàng", "mn": "гарц, үйлдвэрлэлийн хэмжээ"}, {"zh": "软件", "pinyin": "ruǎnjiàn", "mn": "программ хангамж"}]}'::jsonb),
('M52601','listening',1,9,'choice','','[{"key": "A", "text": "注意补充热量"}, {"key": "B", "text": "可以多吃蔬菜"}, {"key": "C", "text": "立即停止减肥"}, {"key": "D", "text": "加强体育锻炼"}]'::jsonb,'B','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «可以多吃一些……蔬菜» гэж зөвлөсөн тул зөв хариулт нь ногоо их идэх.',403.17,446.35,'女：我最近在减肥，饮食上控制热量，经常感觉身体没有力气。
男：那你可以多吃一些热量低但有营养的蔬菜。
女：蔬菜种类太多了，选择哪种比较好？
男：我推荐西蓝花，含有多种维生素，能帮你补充体力，可以多吃一些。
问：男的建议女的怎么做？','{"transcript": [{"zh": "女：我最近在减肥，饮食上控制热量，经常感觉身体没有力气。", "pinyin": "nǚ: wǒ zuì jìn zài jiǎn féi， yǐn shí shàng kòng zhì rè liàng， jīng cháng gǎn jué shēn tǐ méi yǒu lì qì。", "mn": "Эм: Би сүүлийн үед турж байгаа, хоолны илчлэгээ хязгаарлаад байгаа болохоор бие хүчгүй санагддаг."}, {"zh": "男：那你可以多吃一些热量低但有营养的蔬菜。", "pinyin": "nán: nà nǐ kě yǐ duō chī yī xiē rè liàng dī dàn yǒu yíng yǎng de shū cài。", "mn": "Эр: Тэгвэл илчлэг багатай, тэжээллэг ногоо их идээрэй."}, {"zh": "女：蔬菜种类太多了，选择哪种比较好？", "pinyin": "nǚ: shū cài zhǒng lèi tài duō le， xuǎn zé nǎ zhǒng bǐ jiào hǎo？", "mn": "Эм: Ногооны төрөл их юм, аль нь дээр вэ?"}, {"zh": "男：我推荐西蓝花，含有多种维生素，能帮你补充体力，可以多吃一些。", "pinyin": "nán: wǒ tuī jiàn xī lán huā， hán yǒu duō zhǒng wéi shēng sù， néng bāng nǐ bǔ chōng tǐ lì， kě yǐ duō chī yī xiē。", "mn": "Эр: Би брокколи санал болгоно. Олон төрлийн витамин агуулдаг, хүч нэмнэ, их идсэн ч болно."}, {"zh": "问：男的建议女的怎么做？", "pinyin": "wèn: nán de jiàn yì nǚ de zěn me zuò？", "mn": "Асуулт: Эр эмэгтэйд яаж хийхийг зөвлөсөн бэ?"}], "key": "你可以多吃一些热量低但有营养的蔬菜", "keyMn": "Илчлэг багатай, тэжээллэг ногоог илүү их ид", "why": "Эр «可以多吃一些……蔬菜» гэж зөвлөсөн тул зөв хариулт нь ногоо их идэх.", "wrong": {"A": "Эр илчлэг багатай ногоо идэхийг хэлсэн, илчлэг нэмэхийг хэлээгүй.", "C": "Турахаа больж болно гэж хэлээгүй.", "D": "Биеийн тамирын тухай ярианд байхгүй."}, "words": [{"zh": "减肥", "pinyin": "jiǎnféi", "mn": "турах"}, {"zh": "热量", "pinyin": "rèliàng", "mn": "илчлэг"}, {"zh": "蔬菜", "pinyin": "shūcài", "mn": "ногоо"}, {"zh": "维生素", "pinyin": "wéishēngsù", "mn": "витамин"}]}'::jsonb),
('M52601','listening',1,10,'choice','','[{"key": "A", "text": "生日"}, {"key": "B", "text": "元旦"}, {"key": "C", "text": "中秋"}, {"key": "D", "text": "春节"}]'::jsonb,'D','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'«过年», «年夜饭», «饺子», «压岁钱» нь бүгд Хаврын баяр буюу цагаан сарын шинж. «过年» гэдэг нь «过春节» гэсэн үг.',446.65,504.02,'男：今年过年的年夜饭咱们吃什么？
女：还是老样子，凉的、热的一共八个菜，有儿子爱吃的炸鱼、女儿爱吃的烤鸭……
男：饺子还是吃肉三鲜的和黄瓜鸡蛋的两种？
女：对。你别忘了给孙子、孙女儿准备压岁钱。
问：他们在为了什么做准备？','{"transcript": [{"zh": "男：今年过年的年夜饭咱们吃什么？", "pinyin": "nán: jīn nián guò nián de nián yè fàn zán men chī shén me？", "mn": "Эр: Энэ жил шинэ жилийн өдрийн оройн хоолонд бид юу идэх вэ?"}, {"zh": "女：还是老样子，凉的、热的一共八个菜，有儿子爱吃的炸鱼、女儿爱吃的烤鸭……", "pinyin": "nǚ: hái shì lǎo yàng zi， liáng de、 rè de yī gòng bā gè cài， yǒu ér zi ài chī de zhá yú、 nǚ ér ài chī de kǎo yā ……", "mn": "Эм: Урьдын адил, хүйтэн, халуун нийт найман хоол. Хүүгийн дуртай шарсан загас, охины дуртай шарсан нугас гээд..."}, {"zh": "男：饺子还是吃肉三鲜的和黄瓜鸡蛋的两种？", "pinyin": "nán: jiǎo zi hái shì chī ròu sān xiān de hé huáng guā jī dàn de liǎng zhǒng？", "mn": "Эр: Банш нь өмнөх шиг махтай гурван төрөлтэй, өргөст хэмхтэй өндөгтэй хоёр уу?"}, {"zh": "女：对。你别忘了给孙子、孙女儿准备压岁钱。", "pinyin": "nǚ: duì。 nǐ bié wàng le gěi sūn zi、 sūn nǚ ér zhǔn bèi yā suì qián。", "mn": "Эм: Тийм. Ач, зээ нартаа шинэ жилийн мөнгө бэлдэхээ битгий мартаарай."}, {"zh": "问：他们在为了什么做准备？", "pinyin": "wèn: tā men zài wèi le shén me zuò zhǔn bèi？", "mn": "Асуулт: Тэд юуны бэлтгэл хийж байна вэ?"}], "key": "过年、年夜饭、饺子、压岁钱", "keyMn": "Шинэ жил, шинэ жилийн оройн хоол, банш, шинэ жилийн мөнгө", "why": "«过年», «年夜饭», «饺子», «压岁钱» нь бүгд Хаврын баяр буюу цагаан сарын шинж. «过年» гэдэг нь «过春节» гэсэн үг.", "wrong": {"A": "Төрсөн өдөр бялуу иддэг.", "B": "Шинэ жилийн нэгний (元旦) үед тусгай хоол байдаггүй.", "C": "Дундад намрын баярт «月饼» иддэг."}, "words": [{"zh": "过年", "pinyin": "guònián", "mn": "шинэ жил (цагаан сар) тэмдэглэх"}, {"zh": "年夜饭", "pinyin": "niányèfàn", "mn": "шинэ жилийн өмнөх оройн хоол"}, {"zh": "饺子", "pinyin": "jiǎozi", "mn": "банш"}, {"zh": "压岁钱", "pinyin": "yāsuìqián", "mn": "шинэ жилийн мөнгө"}]}'::jsonb),
('M52601','listening',1,11,'choice','','[{"key": "A", "text": "一起去电视台看"}, {"key": "B", "text": "在学校集体观看"}, {"key": "C", "text": "回家守着电视看"}, {"key": "D", "text": "一起去电影院看"}]'::jsonb,'C','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эмэгтэй «守着电视等它开播» гэсэн, тэгэхээр гэртээ очиж телевизээр үздэг байсан.',504.32,604.45,'女：你小时候最爱看什么动画片？我印象中，以前电视台放的动画片都很有意思。
男：我最爱看《葫芦兄弟》。感觉老动画片中人物说话时的发音都很独特，还有片头歌曲，到现在我都记得怎么唱。
女：我也是！那时候放学就赶紧跑回家，和小伙伴们一起守着电视等它开播。
男：那可是经典动画片啊，每个葫芦娃的命运都牵动着我们的心。
女：不同年代的动画片感觉差别挺大的，也不知道现在的孩子都喜欢看什么。
男：现在的动画片主题更加丰富了，还有不少大制作的动画电影，引进的国外动画片也越来越多了。
问：他们小时候怎么收看动画片？','{"transcript": [{"zh": "女：你小时候最爱看什么动画片？我印象中，以前电视台放的动画片都很有意思。", "pinyin": "nǚ: nǐ xiǎo shí hòu zuì ài kàn shén me dòng huà piàn？ wǒ yìn xiàng zhōng， yǐ qián diàn shì tái fàng de dòng huà piàn dōu hěn yǒu yì si。", "mn": "Эм: Чи багадаа ямар хүүхэлдэйн кинонд хамгийн дуртай байсан бэ? Миний санаж байгаагаар телевизээр гардаг хүүхэлдэйн кинонууд их сонирхолтой байсан."}, {"zh": "男：我最爱看《葫芦兄弟》。感觉老动画片中人物说话时的发音都很独特，还有片头歌曲，到现在我都记得怎么唱。", "pinyin": "nán: wǒ zuì ài kàn 《hú lú xiōng dì》。 gǎn jué lǎo dòng huà piàn zhōng rén wù shuō huà shí de fā yīn dōu hěn dú tè， hái yǒu piàn tóu gē qǔ， dào xiàn zài wǒ dōu jì de zěn me chàng。", "mn": "Эр: Би «Хулуу ах дүүс»-д хамгийн их дуртай байсан. Хуучин хүүхэлдэйн киноны дүрүүдийн хоолой онцгой санагддаг, нээлтийн дууг одоо хүртэл дуулж чадна."}, {"zh": "女：我也是！那时候放学就赶紧跑回家，和小伙伴们一起守着电视等它开播。", "pinyin": "nǚ: wǒ yě shì！ nà shí hòu fàng xué jiù gǎn jǐn pǎo huí jiā， hé xiǎo huǒ bàn men yì qǐ shǒu zhe diàn shì děng tā kāi bō。", "mn": "Эм: Би ч гэсэн! Тэр үед сургуулиасаа тарангуутаа гэр лүүгээ гүйж очоод, найзуудтайгаа хамт телевизийн өмнө эхлэхийг хүлээдэг байсан."}, {"zh": "男：那可是经典动画片啊，每个葫芦娃的命运都牵动着我们的心。", "pinyin": "nán: nà kě shì jīng diǎn dòng huà piàn a， měi gè hú lú wá de mìng yùn dōu qiān dòng zhe wǒ men de xīn。", "mn": "Эр: Тэр бол сонгодог хүүхэлдэйн кино шүү дээ, хулуу хүү бүрийн хувь тавилан бидний зүрхийг хөдөлгөдөг байсан."}, {"zh": "女：不同年代的动画片感觉差别挺大的，也不知道现在的孩子都喜欢看什么。", "pinyin": "nǚ: bù tóng nián dài de dòng huà piàn gǎn jué chā bié tǐng dà de， yě bù zhī dào xiàn zài de hái zi dōu xǐ huān kàn shén me。", "mn": "Эм: Үе үеийн хүүхэлдэйн кино нэлээд өөр санагддаг. Одоогийн хүүхдүүд юунд дуртай бол оо."}, {"zh": "男：现在的动画片主题更加丰富了，还有不少大制作的动画电影，引进的国外动画片也越来越多了。", "pinyin": "nán: xiàn zài de dòng huà piàn zhǔ tí gèng jiā fēng fù le， hái yǒu bù shǎo dà zhì zuò de dòng huà diàn yǐng， yǐn jìn de guó wài dòng huà piàn yě yuè lái yuè duō le。", "mn": "Эр: Одоогийн хүүхэлдэйн киноны сэдэв илүү баялаг болсон, томоохон бүтээлтэй хүүхэлдэйн кинонууд ч олон, гаднаас оруулж ирсэн хүүхэлдэйн кино ч улам олширч байна."}, {"zh": "问：他们小时候怎么收看动画片？", "pinyin": "wèn: tā men xiǎo shí hòu zěn me shōu kàn dòng huà piàn？", "mn": "Асуулт: Тэд багадаа хүүхэлдэйн киног яаж үздэг байсан бэ?"}], "key": "放学就赶紧跑回家……守着电视等它开播", "keyMn": "Тарангуутаа гэртээ гүйж очоод телевизийн өмнө хүлээдэг байсан", "why": "Эмэгтэй «守着电视等它开播» гэсэн, тэгэхээр гэртээ очиж телевизээр үздэг байсан.", "wrong": {"A": "Хүүхэлдэйн киног телевизийн станц нэвтрүүлдэг, тэд станц дээр очиж үзээгүй.", "B": "«放学……跑回家» гэснээр сургуульд хамт үзээгүй нь тодорхой.", "D": "Одоо хүүхэлдэйн кино олон байгааг хэлсэн, багадаа кино театрт үзсэн гэж хэлээгүй."}, "words": [{"zh": "动画片", "pinyin": "dònghuàpiàn", "mn": "хүүхэлдэйн кино"}, {"zh": "放学", "pinyin": "fàngxué", "mn": "сургууль тарах"}, {"zh": "守着", "pinyin": "shǒuzhe", "mn": "хүлээн сууж байх"}, {"zh": "开播", "pinyin": "kāibō", "mn": "нэвтрүүлэг эхлэх"}]}'::jsonb),
('M52601','listening',1,12,'choice','','[{"key": "A", "text": "音乐动画"}, {"key": "B", "text": "动画电影"}, {"key": "C", "text": "外国动画片"}, {"key": "D", "text": "中国经典动画片"}]'::jsonb,'D','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «Хулуу ах дүүс»-ийг хамгийн их үзэж байсан гэж хэлж, «经典动画片» гэсэн тул Хятадын сонгодог хүүхэлдэйн кино.',504.32,604.45,'女：你小时候最爱看什么动画片？我印象中，以前电视台放的动画片都很有意思。
男：我最爱看《葫芦兄弟》。感觉老动画片中人物说话时的发音都很独特，还有片头歌曲，到现在我都记得怎么唱。
女：我也是！那时候放学就赶紧跑回家，和小伙伴们一起守着电视等它开播。
男：那可是经典动画片啊，每个葫芦娃的命运都牵动着我们的心。
女：不同年代的动画片感觉差别挺大的，也不知道现在的孩子都喜欢看什么。
男：现在的动画片主题更加丰富了，还有不少大制作的动画电影，引进的国外动画片也越来越多了。
问：男的小时候最爱看的是什么动画片？','{"transcript": [{"zh": "女：你小时候最爱看什么动画片？我印象中，以前电视台放的动画片都很有意思。", "pinyin": "nǚ: nǐ xiǎo shí hòu zuì ài kàn shén me dòng huà piàn？ wǒ yìn xiàng zhōng， yǐ qián diàn shì tái fàng de dòng huà piàn dōu hěn yǒu yì si。", "mn": "Эм: Чи багадаа ямар хүүхэлдэйн кинонд хамгийн дуртай байсан бэ? Миний санаж байгаагаар телевизээр гардаг хүүхэлдэйн кинонууд их сонирхолтой байсан."}, {"zh": "男：我最爱看《葫芦兄弟》。感觉老动画片中人物说话时的发音都很独特，还有片头歌曲，到现在我都记得怎么唱。", "pinyin": "nán: wǒ zuì ài kàn 《hú lú xiōng dì》。 gǎn jué lǎo dòng huà piàn zhōng rén wù shuō huà shí de fā yīn dōu hěn dú tè， hái yǒu piàn tóu gē qǔ， dào xiàn zài wǒ dōu jì de zěn me chàng。", "mn": "Эр: Би «Хулуу ах дүүс»-д хамгийн их дуртай байсан. Хуучин хүүхэлдэйн киноны дүрүүдийн хоолой онцгой санагддаг, нээлтийн дууг одоо хүртэл дуулж чадна."}, {"zh": "女：我也是！那时候放学就赶紧跑回家，和小伙伴们一起守着电视等它开播。", "pinyin": "nǚ: wǒ yě shì！ nà shí hòu fàng xué jiù gǎn jǐn pǎo huí jiā， hé xiǎo huǒ bàn men yì qǐ shǒu zhe diàn shì děng tā kāi bō。", "mn": "Эм: Би ч гэсэн! Тэр үед сургуулиасаа тарангуутаа гэр лүүгээ гүйж очоод, найзуудтайгаа хамт телевизийн өмнө эхлэхийг хүлээдэг байсан."}, {"zh": "男：那可是经典动画片啊，每个葫芦娃的命运都牵动着我们的心。", "pinyin": "nán: nà kě shì jīng diǎn dòng huà piàn a， měi gè hú lú wá de mìng yùn dōu qiān dòng zhe wǒ men de xīn。", "mn": "Эр: Тэр бол сонгодог хүүхэлдэйн кино шүү дээ, хулуу хүү бүрийн хувь тавилан бидний зүрхийг хөдөлгөдөг байсан."}, {"zh": "女：不同年代的动画片感觉差别挺大的，也不知道现在的孩子都喜欢看什么。", "pinyin": "nǚ: bù tóng nián dài de dòng huà piàn gǎn jué chā bié tǐng dà de， yě bù zhī dào xiàn zài de hái zi dōu xǐ huān kàn shén me。", "mn": "Эм: Үе үеийн хүүхэлдэйн кино нэлээд өөр санагддаг. Одоогийн хүүхдүүд юунд дуртай бол оо."}, {"zh": "男：现在的动画片主题更加丰富了，还有不少大制作的动画电影，引进的国外动画片也越来越多了。", "pinyin": "nán: xiàn zài de dòng huà piàn zhǔ tí gèng jiā fēng fù le， hái yǒu bù shǎo dà zhì zuò de dòng huà diàn yǐng， yǐn jìn de guó wài dòng huà piàn yě yuè lái yuè duō le。", "mn": "Эр: Одоогийн хүүхэлдэйн киноны сэдэв илүү баялаг болсон, томоохон бүтээлтэй хүүхэлдэйн кинонууд ч олон, гаднаас оруулж ирсэн хүүхэлдэйн кино ч улам олширч байна."}, {"zh": "问：男的小时候最爱看的是什么动画片？", "pinyin": "wèn: nán de xiǎo shí hòu zuì ài kàn de shì shén me dòng huà piàn？", "mn": "Асуулт: Эр багадаа ямар хүүхэлдэйн кинонд хамгийн их дуртай байсан бэ?"}], "key": "我最爱看《葫芦兄弟》……那可是经典动画片", "keyMn": "Би «Хулуу ах дүүс»-д хамгийн их дуртай байсан, тэр бол сонгодог", "why": "Эр «Хулуу ах дүүс»-ийг хамгийн их үзэж байсан гэж хэлж, «经典动画片» гэсэн тул Хятадын сонгодог хүүхэлдэйн кино.", "wrong": {"A": "Нээлтийн дууг санаж байгаа ч хөгжмийн хүүхэлдэйн кино гэж хэлээгүй.", "B": "Одоо хүүхэлдэйн кино олон байгааг хэлсэн, «Хулуу ах дүүс» тэр биш.", "C": "Гадаадын хүүхэлдэйн кино одоо олширч байгаа тухай ярьсан."}, "words": [{"zh": "葫芦兄弟", "pinyin": "húlu xiōngdì", "mn": "Хулуу ах дүүс"}, {"zh": "经典", "pinyin": "jīngdiǎn", "mn": "сонгодог"}, {"zh": "片头歌曲", "pinyin": "piàntóu gēqǔ", "mn": "нээлтийн дуу"}, {"zh": "引进", "pinyin": "yǐnjìn", "mn": "гаднаас оруулах"}]}'::jsonb),
('M52601','listening',1,13,'choice','','[{"key": "A", "text": "资金不够充足"}, {"key": "B", "text": "缺少先进技术"}, {"key": "C", "text": "新产品利润低"}, {"key": "D", "text": "利益分配不公平"}]'::jsonb,'A','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр «资金比较紧张» гэсэн, эмэгтэй «这个情况我了解» гэж баталсан тул үндсэн асуудал нь хөрөнгө дутагдал.',604.75,697.44,'男：咱们公司正在研发一种新的智能手表，可是资金比较紧张，大大影响了产品的研发速度。
女：这个情况我了解。不过好在咱们还是有技术优势的，这个产品创新性强，利润空间也会比较大。
男：所以我在想，能不能以此吸引其他企业投入资金，和他们联合起来，一起承担研发成本。
女：这个主意不错，联合后能整合资源，后期也可以分担产品宣传和推广的投入。
男：不过联合也会面临不少问题，比如利益分配什么的。
女：只要提前商量好，明确各方的利益分配，应该问题不大。
问：公司现在面临的主要问题是什么？','{"transcript": [{"zh": "男：咱们公司正在研发一种新的智能手表，可是资金比较紧张，大大影响了产品的研发速度。", "pinyin": "nán: zán men gōng sī zhèng zài yán fā yī zhǒng xīn de zhì néng shǒu biǎo， kě shì zī jīn bǐ jiào jǐn zhāng， dà dà yǐng xiǎng le chǎn pǐn de yán fā sù dù。", "mn": "Эр: Манай компани шинэ ухаалаг цаг боловсруулж байгаа ч санхүүгийн хүндрэлтэй байгаа нь бүтээгдэхүүний боловсруулалтын хурдад ихээхэн нөлөөлж байна."}, {"zh": "女：这个情况我了解。不过好在咱们还是有技术优势的，这个产品创新性强，利润空间也会比较大。", "pinyin": "nǚ: zhè ge qíng kuàng wǒ liǎo jiě。 bù guò hǎo zài zán men hái shì yǒu jì shù yōu shì de， zhè ge chǎn pǐn chuàng xīn xìng qiáng， lì rùn kōng jiān yě huì bǐ jiào dà。", "mn": "Эм: Би мэдэж байна. Гэхдээ манайд технологийн давуу тал бий, энэ бүтээгдэхүүн шинэлэг, ашгийн зай ч нэлээд их байх болно."}, {"zh": "男：所以我在想，能不能以此吸引其他企业投入资金，和他们联合起来，一起承担研发成本。", "pinyin": "nán: suǒ yǐ wǒ zài xiǎng， néng bù néng yǐ cǐ xī yǐn qí tā qǐ yè tóu rù zī jīn， hé tā men lián hé qǐ lái， yì qǐ chéng dān yán fā chéng běn。", "mn": "Эр: Тиймээс би бодсон юм, бусад компаниудыг хөрөнгө оруулахад татаад, тэдэнтэй нэгдэж боловсруулалтын зардлыг хамт хуваалцаж болохгүй юм уу."}, {"zh": "女：这个主意不错，联合后能整合资源，后期也可以分担产品宣传和推广的投入。", "pinyin": "nǚ: zhè ge zhǔ yì bù cuò， lián hé hòu néng zhěng hé zī yuán， hòu qī yě kě yǐ fēn dān chǎn pǐn xuān chuán hé tuī guǎng de tóu rù。", "mn": "Эм: Сайн санаа байна. Нэгдвэл нөөцөө нэгтгэж чадна, дараа нь бүтээгдэхүүний сурталчилгаа, түгээлтийн зардлыг ч хуваалцаж болно."}, {"zh": "男：不过联合也会面临不少问题，比如利益分配什么的。", "pinyin": "nán: bù guò lián hé yě huì miàn lín bù shǎo wèn tí， bǐ rú lì yì fēn pèi shén me de。", "mn": "Эр: Гэхдээ нэгдвэл ашгийг хуваарилах гэх мэт олон асуудал тулгарна."}, {"zh": "女：只要提前商量好，明确各方的利益分配，应该问题不大。", "pinyin": "nǚ: zhǐ yào tí qián shāng liáng hǎo， míng què gè fāng de lì yì fēn pèi， yīng gāi wèn tí bù dà。", "mn": "Эм: Урьдчилан ярилцаж, талууд бүрийн ашгийн хуваарийг тодорхой болгочихвол асуудал тийм ч том биш байх."}, {"zh": "问：公司现在面临的主要问题是什么？", "pinyin": "wèn: gōng sī xiàn zài miàn lín de zhǔ yào wèn tí shì shén me？", "mn": "Асуулт: Компани одоо голлон ямар асуудалтай тулгарч байна вэ?"}], "key": "资金比较紧张", "keyMn": "Санхүүгийн хүндрэлтэй байна", "why": "Эр «资金比较紧张» гэсэн, эмэгтэй «这个情况我了解» гэж баталсан тул үндсэн асуудал нь хөрөнгө дутагдал.", "wrong": {"B": "Эмэгтэй «有技术优势» гэсэн, технологи дутагдаагүй.", "C": "Эмэгтэй «利润空间会比较大» гэсэн, ашиг бага биш.", "D": "Ашгийн хуваарилалт нь нэгдвэл гарч болзошгүй асуудал, одоогийн асуудал биш."}, "words": [{"zh": "研发", "pinyin": "yánfā", "mn": "судалгаа боловсруулалт"}, {"zh": "资金", "pinyin": "zījīn", "mn": "хөрөнгө"}, {"zh": "利润", "pinyin": "lìrùn", "mn": "ашиг"}, {"zh": "分配", "pinyin": "fēnpèi", "mn": "хуваарилах"}]}'::jsonb),
('M52601','listening',1,14,'choice','','[{"key": "A", "text": "聘请高级人才"}, {"key": "B", "text": "投入更多资源"}, {"key": "C", "text": "与其他企业合作"}, {"key": "D", "text": "重视宣传和推广"}]'::jsonb,'C','auto',1,'/mock-tests/m52601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk5','hsk30']::text[],'Эр санхүүгийн хүндрэлийг даван туулахын тулд «和他们联合起来» гэсэн, өөрөөр хэлбэл бусад компанитай хамтран ажиллана.',604.75,697.44,'男：咱们公司正在研发一种新的智能手表，可是资金比较紧张，大大影响了产品的研发速度。
女：这个情况我了解。不过好在咱们还是有技术优势的，这个产品创新性强，利润空间也会比较大。
男：所以我在想，能不能以此吸引其他企业投入资金，和他们联合起来，一起承担研发成本。
女：这个主意不错，联合后能整合资源，后期也可以分担产品宣传和推广的投入。
男：不过联合也会面临不少问题，比如利益分配什么的。
女：只要提前商量好，明确各方的利益分配，应该问题不大。
